using UnityEngine;
using UnityEngine.InputSystem;
using System.Collections.Generic;
public class WoodlandVisorEffects:MonoBehaviour {
 public WoodlandPlayer player;public Renderer visor;public Transform wipeHand,wipeSleeve;public AudioClip ringing;
 public bool earDefenders;[Range(0,.88f)]public float fog;[Range(0,1)]public float exposure;[System.NonSerialized]public float panicFog;
 public bool Busy{get;private set;} public float RingIntensity=>Mathf.Clamp01((exposure-.24f)/.76f);
 float wipeTime,hold,ringGain;Vector3 rifleRest;MeshFilter handMesh;Vector3[] handVertices;AudioSource ring;MaterialPropertyBlock properties;
 readonly List<AudioLowPassFilter> filters=new List<AudioLowPassFilter>();
 public const float WipeDuration=2.15f;
 void Start(){var tone=new GameObject("Hearing ring (unfiltered)");tone.transform.SetParent(transform,false);ring=tone.AddComponent<AudioSource>();ring.clip=ringing;ring.loop=true;ring.playOnAwake=false;ring.spatialBlend=0;ring.volume=0;if(ringing)ring.Play();foreach(var source in FindObjectsByType<AudioSource>(FindObjectsSortMode.None)){if(source==ring||source.GetComponent<AudioLowPassFilter>())continue;var f=source.gameObject.AddComponent<AudioLowPassFilter>();f.cutoffFrequency=22000;filters.Add(f);}}
 void Update(){if(WoodlandDemoControls.Paused)return;if(!Application.isFocused||Cursor.lockState!=CursorLockMode.Locked){if(ring)ring.volume=0;return;}float dt=Mathf.Min(Time.deltaTime,.05f);var k=Keyboard.current;if(k!=null&&k.cKey.wasPressedThisFrame)BeginWipe();bool moving=k!=null&&(k.wKey.isPressed||k.aKey.isPressed||k.sKey.isPressed||k.dKey.isPressed);bool sprint=player&&player.IsSprinting;Advance(dt,sprint);}
 public void RoarExposure(){exposure=Mathf.Max(exposure,earDefenders?.35f:.72f);hold=3.5f;}
 public void Shot(){fog=Mathf.Min(.88f,fog+.004f);exposure=Mathf.Min(1,exposure+(earDefenders?.012f:.18f));hold=1.75f;}
 public bool BeginWipe(){if(Busy||!player||(player.fieldKit&&player.fieldKit.Busy)||(player.equipment&&player.equipment.HandsBusy)||(player.anatomy&&player.anatomy.Incapacitated)||player.IsReloading||(player.nodeRepair&&player.nodeRepair.Busy)||player.pack.gameObject.activeSelf)return false;if(!handMesh){handMesh=wipeHand.GetComponentInChildren<MeshFilter>();if(handMesh&&handMesh.sharedMesh.isReadable)handVertices=handMesh.sharedMesh.vertices;}rifleRest=player.rifle.localPosition;Busy=true;wipeTime=0;return true;}
 public void Advance(float dt,bool sprint){fog=Mathf.Clamp(fog+dt*(sprint?Mathf.Lerp(.0105f,.0195f,player?player.Exertion:0):-.012f),0,.88f);if(hold>0)hold=Mathf.Max(0,hold-dt);else exposure=Mathf.Max(0,exposure-dt*.045f);if(Busy){wipeTime+=dt;if(wipeTime>=WipeDuration){fog*=.025f;Busy=false;player.rifle.localPosition=rifleRest;}}ApplyVisual();float target=RingIntensity>.005f?Mathf.Pow(10,Mathf.Lerp(-29,-10,RingIntensity)/20):0;ringGain=Mathf.Lerp(ringGain,target,1-Mathf.Exp(-7*dt));if(ring)ring.volume=ringGain;foreach(var f in filters)if(f)f.cutoffFrequency=Mathf.Min(earDefenders?10000:20000,Mathf.Lerp(20000,3900,RingIntensity));}
 public void ApplyVisual(){if(properties==null)properties=new MaterialPropertyBlock();if(visor){visor.GetPropertyBlock(properties);properties.SetFloat("_Fog",Mathf.Clamp(fog+panicFog,0,.88f));properties.SetFloat("_Wipe",Busy?Mathf.Lerp(-.18f,1.18f,Mathf.SmoothStep(0,1,Mathf.InverseLerp(.4f,1.65f,wipeTime))):-.2f);visor.SetPropertyBlock(properties);}if(wipeHand){wipeHand.gameObject.SetActive(Busy);if(Busy){float u=Mathf.Clamp01(wipeTime/WipeDuration);float raise=Mathf.SmoothStep(0,1,Mathf.Clamp01(u/.18f))*(1-Mathf.SmoothStep(0,1,Mathf.Clamp01((u-.82f)/.18f)));float sweep=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.18f,.82f,u));wipeHand.localPosition=new Vector3(Mathf.Lerp(-.17f,.19f,sweep),Mathf.Lerp(-.44f,-.035f+Mathf.Sin(sweep*Mathf.PI)*.035f,raise),.36f);wipeHand.localRotation=Quaternion.Euler(-65,180,Mathf.Lerp(55,35,sweep));}if(wipeSleeve){wipeSleeve.gameObject.SetActive(Busy);if(Busy){Vector3 wrist=WristPoint();Vector3 elbow=new Vector3(wrist.x-.05f,-.48f,.18f);wipeSleeve.localPosition=(wrist+elbow)*.5f;wipeSleeve.localRotation=Quaternion.FromToRotation(Vector3.up,wrist-elbow);wipeSleeve.localScale=new Vector3(.082f,Vector3.Distance(wrist,elbow)*.5f,.082f);}}}}
 Vector3 WristPoint(){
 if(handVertices!=null&&handVertices.Length>0){var matrix=player.eye.transform.worldToLocalMatrix*handMesh.transform.localToWorldMatrix;float min=float.MaxValue;foreach(var v in handVertices)min=Mathf.Min(min,matrix.MultiplyPoint3x4(v).y);Vector3 sum=Vector3.zero;int count=0;foreach(var v in handVertices){var p=matrix.MultiplyPoint3x4(v);if(p.y<min+.018f){sum+=p;count++;}}if(count>0)return sum/count+Vector3.up*.075f;}
 var r=wipeHand.GetComponentInChildren<Renderer>();return player.eye.transform.InverseTransformPoint(r.bounds.center-Vector3.up*r.bounds.extents.y)+Vector3.up*.075f;
 }
 void LateUpdate(){if(Busy&&player){float u=wipeTime/WipeDuration;float lower=Mathf.SmoothStep(0,1,Mathf.Clamp01(u/.16f))*(1-Mathf.SmoothStep(0,1,Mathf.Clamp01((u-.85f)/.15f)));player.rifle.localPosition=rifleRest+Vector3.down*.65f*lower;player.rifle.gameObject.SetActive(u<.17f||u>.85f);if(player.adsRifle)player.adsRifle.gameObject.SetActive(false);if(player.focusRifle)player.focusRifle.gameObject.SetActive(false);player.watch.gameObject.SetActive(false);}}
 public void Cancel(){if(Busy&&player)player.rifle.localPosition=rifleRest;Busy=false;ApplyVisual();if(ring)ring.volume=0;foreach(var f in filters)if(f)f.cutoffFrequency=22000;}
 void OnDisable(){Cancel();}void OnApplicationFocus(bool focus){if(!focus)Cancel();}void OnApplicationPause(bool paused){if(paused)Cancel();}
}
